/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Delete File: TopModule.sv
*** End Patch
PATCH
cat > TopModule.sv <<'EOF'
module TopModule(
	input clk,
	input rst_n,
	input a,
	output match
	);

	reg [8:0] a_tem;
	reg match_b;

	always @(posedge clk or negedge rst_n)
		if ("'!rst_n)
			begin
				a_tem <= 9'"'b0;
				match_b <= 1'b0;
			end
		else
			begin
				a_tem <= {a_tem[7:0], a};
				match_b <= ({a_tem[7:0], a}[8:6] == 3'b011) && ({a_tem[7:0], a}[2:0] == 3'b110);
			end

	assign match = match_b;
endmodule
EOF
cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg a = 0;
  wire match;
  reg [8:0] hist;
  integer i;

  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));

  always #5 clk = ~clk;

  task drive_bit(input reg bitval);
    reg expected;
    begin
      a = bitval;
      @(posedge clk);
      hist = {hist[7:0], bitval};
      expected = (hist[8:6] == 3'b011) && (hist[2:0] == 3'b110);
      #1;
      if (match "'!== expected) begin
        $display("FAIL i=%0d hist=%b a=%b match=%b expected=%b", i, hist, bitval, match, expected);
        $finish;
      end
    end
  endtask

  initial begin
    hist = 9'"'b0;
    repeat (2) @(posedge clk);
    rst_n = 1;

    for (i = 0; i < 40; i = i + 1)
      drive_bit("'$random);

    hist = 9'"'b0;
    rst_n = 0;
    @(posedge clk);
    @(negedge clk);
    rst_n = 1;
    drive_bit(0);
    drive_bit(1);
    drive_bit(1);
    drive_bit(0);
    drive_bit(0);
    drive_bit(1);
    drive_bit(1);
    drive_bit(1);
    drive_bit(0);

    "'$display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

